id","recordId":"uuid","versionId":"uuid","expectedRevision":"integer"},"result":{"record":"Record","version":"RecordVersion"},"authority":"author; obligations owner only"},"recordReview":{"request":{"studyId":"uuid","partnerId":"uuid","recordId":"uuid","versionId":"uuid","expectedRevision":"integer","decision":"target RecordStatus","note":"string?","approvedTerms":"ApprovedTerms? contribution only","cancellationAgreementVersionId":"uuid? obligation cancellation only","viewerPartnerIds":"uuid[]? analysis_result publication or approved contribution only","downloadPartnerIds":"uuid[]? subset of explicit viewers"},"result":{"record":"Record","review":"Review"},"authority":"owner"},"recordVersions":{"request":{"studyId":"uuid","partnerId":"uuid","recordId":"uuid"},"result":{"versions":"RecordVersionSummary[]"},"authority":"owner or author; publication viewers see released version only"},"findingPublish":{"request":{"studyId":"uuid","partnerId":"uuid","recordId":"uuid","versionId":"uuid","expectedRevision":"integer","viewerPartnerIds":"uuid[]","downloadPartnerIds":"uuid[]"},"result":{"record":"Record","publication":"Publication"},"authority":"owner; exact approved version; privacy and consent review"},"findingWithdraw":{"request":{"studyId":"uuid","partnerId":"uuid","recordId":"uuid","versionId":"uuid","expectedRevision":"integer","reason":"string"},"result":{"record":"Record"},"authority":"owner"},"findingComment":{"request":{"studyId":"uuid","partnerId":"uuid","recordId":"uuid","versionId":"uuid","text":"string"},"result":{"comment":"FindingComment"},"authority":"authorized published viewer with comment_on_findings"},"partnerInviteCreate":{"request":{"studyId":"uuid","partnerId":"uuid","expiresAt":"ISO timestamp?","preset":"AccessPreset","permissions":"string[]?"},"result":{"invitation":"PartnerInvitation","delivery":"DeliveryState"},"authority":"owner"},"partnerInviteGet":{"request":{"invite":"opaque token"},"result":{"invitation":"PartnerInvitationPreview"},"authority":"verified invited individual only"},"partnerInviteAccept":{"request":{"invite":"opaque token"},"result":{"partner":"Partner","workspace":"WorkspaceSummary"},"authority":"verified invited individual only"},"partnerInviteRevoke":{"request":{"studyId":"uuid","partnerId":"uuid","invitationId":"uuid","expectedRevision":"integer"},"result":{"invitation":"PartnerInvitation"},"authority":"owner"},"agreementApprove":{"request":{"studyId":"uuid","partnerId":"uuid","recordId":"uuid","versionId":"uuid","expectedRevision":"integer","documentHash":"sha256","ipExplanationVersionId":"uuid","ipReadAcknowledged":"true"},"result":{"record":"Record","approval":"AgreementApproval","approvals":"AgreementApproval[]"},"authority":"actual owner or actual partner; same version/hash"},"agreementAmend":{"request":{"studyId":"uuid","partnerId":"uuid","recordId":"uuid","versionId":"uuid","expectedRevision":"integer","data":"AgreementData","reason":"string"},"result":{"record":"Record","version":"RecordVersion"},"authority":"actual owner or actual partner; new agreement record referencing executed source"},"signingStart":{"request":{"studyId":"uuid","partnerId":"uuid","recordId":"uuid","versionId":"uuid","expectedRevision":"integer","documentHash":"sha256","consent":"true"},"result":{"signing":"SigningSession"},"authority":"owner; both exact-version approvals and operational provider"},"signingView":{"request":{"studyId":"uuid","partnerId":"uuid","recordId":"uuid","signingId":"uuid"},"result":{"signing":"SigningSession"},"authority":"actual owner or actual agreement partner"},"signingRefresh":{"request":{"studyId":"uuid","partnerId":"uuid","recordId":"uuid","signingId":"uuid","expectedRevision":"integer"},"result":{"record":"Record","signing":"SigningSession"},"authority":"actual owner or actual agreement partner; server verifies provider state"},"workspaceDocumentPut":{"request":{"studyId":"uuid","partnerId":"uuid","recordId":"uuid?","filename":"string","mediaType":"allowlisted MIME","contentBase64":"bounded base64"},"result":{"document":"PrivateDocumentMetadata"},"authority":"owner or actual folder author; private server encrypted storage"},"workspaceDocumentGet":{"request":{"studyId":"uuid","partnerId":"uuid","documentId":"uuid","download":"boolean?"},"result":{"document":"PrivateDocumentMetadata","contentBase64":"base64"},"authority":"current folder/record/version authorization; separate release/download rights"},"workspaceExport":{"request":{"studyId":"uuid","partnerId":"uuid","recordId":"uuid","versionId":"uuid","format":"text|json|html|docx"},"result":{"filename":"string","mediaType":"MIME","contentBase64":"base64","versionId":"uuid","documentHash":"sha256"},"authority":"current exact-version read AND applicable export/download rights; PDF via authorized HTML and native browser print"},"workspaceImpact":{"request":{"studyId":"uuid","partnerId":"uuid","recordId":"uuid","fromVersionId":"uuid","toVersionId":"uuid","includeAI":"boolean?"},"result":{"changes":"FieldChange[]","approvalsInvalidated":"boolean","binding":"false","ai":"ImpactAIState"},"authority":"owner or actual record author"},"workspaceAnalysis":{"request":{"studyId":"uuid","partnerId":"uuid","requestRecordId":"uuid","sourceSnapshotId":"uuid? omit to create consent-bound snapshot","operation":"AnalysisOperation"},"result":{"operation":"AnalysisOperation","sourceSnapshotId":"uuid","summary":"ApprovedAnalysisProjection","provenance":"AnalysisProvenance","record":"Record draft analysis_result","version":"RecordVersion"},"authority":"owner only; approved request and fixed allowlisted parameters; requestId required"}},"reads":["workspaceBootstrap","partnerGet","workspaceList","recordGet","recordVersions","partnerInviteGet","signingView","workspaceDocumentGet","workspaceExport","workspaceImpact","agreementSources","agreementRefreshPreview","processingPolicyGet"],"processingPolicy":[{"id":"purpose","label":"מטרת העברה","type":"enum","choices":{"external_impact":"הסבר שינויים","pre_signing_document":"מסמך לפני חתימה"},"required":true},{"id":"provider","label":"ספק","type":"text","required":true,"maxLength":240},{"id":"providerVersion","label":"גרסת ספק","type":"text","required":true,"maxLength":240},{"id":"dataCategories","label":"סוגי מידע","type":"tags","required":true,"choices":["agreement_changes","agreement_document","personal","confidential"]},{"id":"authorizedActors","label":"מורשות גישה","type":"tags","required":true},{"id":"partyRoles","label":"partyRoles","type":"text","required":true},{"id":"transferBasis","label":"transferBasis","type":"text","required":true},{"id":"storageLocation","label":"storageLocation","type":"text","required":true},{"id":"retention","label":"retention","type":"text","required":true},{"id":"backups","label":"backups","type":"text","required":true},{"id":"deletion","label":"deletion","type":"text","required":true},{"id":"withdrawal","label":"withdrawal","type":"text","required":true},{"id":"securityMeasures","label":"securityMeasures","type":"text","required":true},{"id":"ethicsReference","label":"ethicsReference","type":"text","required":true},{"id":"consentReview","label":"consentReview","type":"text","required":true}]}$operations$::jsonb $f$;
ALTER FUNCTION research_private.intake_contract() RENAME TO intake_contract_before_guided;
CREATE FUNCTION research_private.intake_contract() RETURNS jsonb LANGUAGE sql IMMUTABLE SET search_path='' AS $f$
 SELECT pg_catalog.jsonb_set(research_private.intake_contract_before_guided(),'{operations}',$operations${"intakePublicInfo":{"request":{},"result":{"terms":"IntakeTerms|null","acceptingApplications":"boolean"},"authority":"public; published terms only"},"intakeSubmit":{"request":{"requestId":"uuid","termsVersionId":"uuid","termsHash":"sha256","acknowledged":"true","application":"PublicApplicationData"},"result":{"receipt":"IntakeReceipt {id,status:submitted,submittedAt}"},"authority":"public proposal only; no identity or grants"},"intakeOwnerBootstrap":{"request":{},"result":{"termsState":"IntakeTermsState {revision,draftVersion,publishedVersionId}","identities":"IndividualIdentity[]","institutions":"string[]"},"authority":"owner"},"intakeList":{"request":{"status":"IntakeStatus?","query":"string?","cursor":"string?"},"result":{"applications":"IntakeApplicationSummary[]","nextCursor":"string|null"},"authority":"owner"},"intakeGet":{"request":{"applicationId":"uuid"},"result":{"application":"IntakeApplication","terms":"IntakeTerms","workspace":"WorkspaceSummary?"},"authority":"owner"},"intakeTermsSave":{"request":{"requestId":"uuid","expectedRevision":"integer","title":"string","text":"string"},"result":{"termsState":"IntakeTermsState"},"authority":"owner; proposed draft only"},"intakeTermsPublish":{"request":{"requestId":"uuid","expectedRevision":"integer","versionId":"uuid"},"result":{"termsState":"IntakeTermsState"},"authority":"owner; explicit exact-version publication"},"intakeReview":{"request":{"requestId":"uuid","applicationId":"uuid","expectedRevision":"integer","decision":"under_review|rejected|approved","note":"string?","studyId":"uuid? approval only","studyExpectedRevision":"integer? approval only","individualCode":"string? approval only","permissions":"string[]? approval only; explicit view_study"},"result":{"application":"IntakeApplication","partner":"Partner?","workspace":"WorkspaceSummary?","preparation":"PreparedAgreement?"},"authority":"owner; approval binds selected live identity and explicit study grants"},"intakeIdentityCreate":{"request":{"requestId":"uuid","institution":"string","label":"string"},"result":{"identity":"IndividualIdentity"},"authority":"owner; existing access mechanism; no automatic tool or research grants"}}$operations$::jsonb) $f$;
CREATE FUNCTION research_private.guided_catalog() RETURNS jsonb LANGUAGE sql IMMUTABLE SET search_path='' AS $f$ SELECT $catalog${"catalogVersion":"4","source":{"sha256":"73a22c07e4df4cdac9560b95a77d6284d389e21aebcdacd64acc5e24a4c325ad","filename":"agreement-guided-v4/content.json","bodyPlaceholderCount":19,"sectionCount":12},"templateData":{"title":"טיוטת הסכם לשיתוף פעולה מחקרי ב BE GOOD","templateVersion":"guided-v4","explanationVersion":"guided-v4-ip","sectionClauses":[{"sectionId":"parties","text":"הסכם זה מוצע בין {{ownerName}}, מספר זיהוי או רישום {{ownerRegistration}}, כתובת {{ownerAddress}}, דוא״ל להודעות {{ownerEmail}}, באמצעות {{ownerSignatory}}, {{ownerSignatoryRole}}, להלן ״בעלת המערכת״; לבין {{partnerName}}, מספר זיהוי או רישום {{partnerRegistration}}, כתובת {{partnerAddress}}, דוא״ל להודעות {{partnerEmail}}, באמצעות {{partnerSignatory}}, {{partnerSignatoryRole}}, להלן ״שותפת המחקר״.\n\nהחוקרת האחראית מטעם שותפת המחקר תהיה {{leadResearcher}}, {{leadResearcherRole}}, {{leadResearcherInstitution}}. כל צד יפעל בתחום סמכותו ויקבל את אישורי המוסד או הגורמים מטעמו הדרושים להתקשרות ולביצוע חלקו במחקר. הקשר המקצועי יתנהל באמצעות אנשי הקשר המפורטים בנספח א."},{"sectionId":"study","text":"מזהה המחקר: {{studyIdentifier}}. שם המחקר: {{studyTitle}}. מטרת שיתוף הפעולה המוצעת היא לבחון את השימוש בכלי BE GOOD בהקשר חינוכי מוגדר, את התאמתם לצורכי המשתמשות והמשתמשים ואת התובנות העולות מהשימוש בהם. שאלת המחקר המרכזית תהיה: {{centralResearchQuestion}}.\n\nתוכנית המחקר בנספח א תפרט את שאלות המחקר, השיטה, המסגרות החינוכיות, אוכלוסיית המחקר, דרך הגיוס, כלי המדידה, מועדי הפעילות והתוצרים.\n\nחלוקת האחריות המוצעת: שותפת המחקר תוביל את תכנון המחקר, האישורים, הגיוס, ההסכמות והניתוח, לפי חלוקה שתיקבע בנספח א. בעלת המערכת תספק את הכלים, ההדרכה והתמיכה שהוגדרו במפורש. אין התחייבות לתוצאה מחקרית מסוימת או להוכחת השפעה; המסקנות יתבססו על הנתונים ועל מגבלות המחקר."},{"sectionId":"tools","text":"לשותפת המחקר תינתן הרשאת שימוש אישית ומוגבלת בכלי BE GOOD שיפורטו בנספח ב, לצורכי המחקר המוגדר ולמשך התקופה שתאושר. לכל כלי יירשמו שם וגרסה, המשתמשות המורשות, הפעולות המותרות, היקף השימוש, הגישה לנתונים והאפשרות לייצוא.\n\nהגישה תוגבל למחקר ולסביבת השותפות שהוקצו לכל משתמשת. אין להעביר פרטי כניסה או לתת גישה לאדם נוסף ללא הרשאה נפרדת. שימוש במחקר אחר, בהדרכה חיצונית או בפעילות מסחרית יוסדר מראש לפי היקף ההרשאה והזכויות הרלוונטיות.\n\nשאלונים, מדדים וחומרים חיצוניים ישמשו בהתאם לתנאי השימוש החלים עליהם. הרשאת שימוש במערכת אינה כוללת כשלעצמה מסירת קוד מקור או הרשאת ניהול כללית. אחריות לבדיקה מקצועית של תוצרי AI לפני שימוש חינוכי תוגדר בתוכנית העבודה."},{"sectionId":"contributions","text":"תרומות הצדדים יפורטו בנספח ד: ידע מדעי, תכנון ושיטות, שאלונים ומדידות, תוכן חינוכי, טכנולוגיה, מימון, שירות מקצועי או תרומה אחרת. לכל תרומה יירשמו הגורם התורם, התיאור, התוצר, אבני הדרך, מועד ההשלמה, אופן בדיקת הביצוע וההכרה או התמורה שהתבקשו והוסכמו.\n\nרישום תרומה הוא תחילה הצעה בלבד. אין בהגשתה או באישור פעילות מחקרית כדי ליצור לבדם התחייבות לתשלום, לפיתוח, לשילוב ב BE GOOD, להעברת קניין רוחני, לחלוקת הכנסות או לבלעדיות. התחייבות תירשם כמוסכמת רק לאחר שהוסדרה בתנאים שהצדדים אישרו והשלימו עבורם את הליך ההתקשרות הנדרש.\n\nהנוסח המקורי, הערות הצדדים, התנאים שהוסכמו, שינויים וראיות לביצוע יישמרו כרשומות נפרדות ומקושרות. מסמך תרומה ייחשף רק למי שהורשתה לכך. זכויות בתוכן קודם או בתוצר חדש יוסדרו גם לפי סעיף 8 ונספח ו."},{"sectionId":"sharedExpenses","text":"הוצאות הפעלה לצורך המחקר יפורטו בתקציב שבנספח ג. אפשר לכלול, לפי הצורך, שימוש בשירותי AI, אחסון, רישוי, חתימה אלקטרונית והוצאות תפעול נוספות. לכל פריט ייקבעו מטרתו, בסיס החישוב, מטבע, מסים ככל שחלים, תקרת הוצאה, חלוקת התשלום והגורם המאשר.\n\nהוצאה, חריגה או שירות בתשלום לא יופעלו על חשבון הצד האחר בלי אישור מוקדם ומתועד של הגורם המוסמך ובהתאם לתקציב המוסכם. אופן ההתחשבנות, האסמכתאות ומועד התשלום יפורטו בנספח ג. אין הנחה שהעלויות מתחלקות בחלקים שווים.\n\nהתקציב יבחין בין סכום משוער, תקרה מאושרת והוצאה בפועל. שינוי היוצר התחייבות חוזית חדשה יועבר להסכמה ולחתימה על תיקון לפי סעיף 12."},{"sectionId":"professionalFees","text":"תשלום עבור שירות מקצועי יוסדר בנפרד מהוצאות ההפעלה. לכל שירות יוגדרו נותנת השירות, מקבלת השירות, תכולת העבודה, התוצר, היקף שעות או מחיר קבוע, סכום ומטבע, מסים ככל שחלים, מועדים ותנאי קבלת התוצר.\n\nהתשלום יבוצע בהתאם לאבן הדרך או לתנאי שנקבעו בנספח ג וכנגד המסמכים הנדרשים לפי העניין. עבודה נוספת מעבר להיקף המוסכם תחייב הסכמה מוקדמת על תכולה, מחיר ומועד. ההסכם יפרט גם כיצד מתחשבנים על עבודה מאושרת שכבר בוצעה במקרה של סיום מוקדם.\n\nאין להסיק מכך ששדה תשלום טרם מולא שהשירות ניתן ללא תמורה. אם הצדדים מבקשים להסכים על תרומה ללא תשלום, יש לציין זאת במפורש לצד היקף התרומה והקרדיט שסוכם."},{"sectionId":"development","text":"עבודות פיתוח והתאמה לבית הספר או למחקר ייקבעו בתוכנית עבודה נפרדת. לכל משימה יוגדרו הצורך החינוכי, המשתמשות, השינוי המבוקש, תוצר מדיד, מי מבצעת, עלות אם יש, אבני דרך, סביבת בדיקה ותנאי קבלה. הדרכה, התאמת תוכן ושינוי תוכנה יתוארו בנפרד לפי הצורך.\n\nפיתוח שלא נכלל בתוכנית המאושרת יישאר בגדר בקשה עד להסכמה על היקפו, משאביו, לוחות הזמנים והזכויות בתוצר. אין התחייבות אוטומטית לפיתוח ללא תשלום או לשילוב כל הצעה בגרסה הכללית של BE GOOD. שינוי באתר החי יחייב את אישור בעלת המערכת ובדיקות מתאימות.\n\nהתמיכה תינתן בערוצים, בימים ובהיקף שייקבעו. זמני מענה, תחזוקה והסלמה יוגדרו במפורש; אין התחייבות לזמינות רציפה אם לא סוכמה. שימוש חינוכי בתוצרי AI מחייב שיקול דעת מקצועי ובדיקה אנושית בהתאם לתפקיד."},{"sectionId":"mutualIP","text":"בעלת המערכת מצהירה כי פיתחה את קוד BE GOOD ואת תכניה המקוריים. הספרות המדעית המוזכרת שימשה ללמידה ולביסוס הפיתוח, ללא העתקת טקסטים, טבלאות או איורים ממנה. זכויותיה בקוד ובתכנים המקוריים יישארו בידיה.\n\nהרשאה להשתתף במחקר אינה מקנה כשלעצמה בעלות בנכסי המערכת הקיימים. זכויות בתוצרים חדשים של שיתוף הפעולה יוסדרו בנפרד ובמפורש.\n\nהזכויות הקודמות של שותפת המחקר, של המוסד ושל צדדים שלישיים יישמרו בידי בעלי הזכויות. לפני יצירת תוצר חדש יירשמו בנספח ו היוצרות ובעלי הזכויות, הבעלות המוסכמת, רישיון השימוש, אפשרות שינוי והפצה, שימוש מסחרי, פרסום וקרדיט. אין בטיוטה זו קביעה שקיימים כבר נכסים משותפים."},{"sectionId":"privacyEthics","text":"ההשתתפות במחקר תהיה מרצון ובהתאם להליך ההסכמה ולאישורים שייקבעו למחקר. ההחלטה להשתתף במחקר תופרד מהשימוש המקצועי ב BE GOOD, ולא תהווה תנאי לקבלת שירות שאינו מחייב השתתפות במחקר. לפני איסוף נתונים יושלמו האישורים הנדרשים מהמוסד, מהמסגרת החינוכית ומגורמי האתיקה הרלוונטיים.\n\nנספח ה יפרט את סוגי המידע, מטרות העיבוד, תפקידי הצדדים, ההרשאות, ספקים נוספים, מקום האחסון, תקופות שמירה ומחיקה והליך פרישה מהמחקר. ההודעה למשתתפים תסביר את הבחירה להשתתף ואת זכויותיהם, לרבות מגבלות על הסרה לאחר אִגום בלתי הפיך, ככל שרלוונטי.\n\nכל צד יקבל רק את המידע הנדרש לתפקידו ולמטרה המותרת. בעלות על המערכת אינה מעניקה כשלעצמה הרשאה לעיין במידע אישי של משתתפים. ייקבעו הפרדת הרשאות, הגנה על מסמכים, טיפול בבקשות ובאירועים, ואחראית לפניות. מידע אישי לא יועבר לספק AI חיצוני לפני שהוסדרו ונבדקו תנאי העיבוד והבסיס המתאים להעברה.\n\nמידע סודי שיימסר לצורך השותפות ישמש רק למטרה שהותרה ויוגן מפני גילוי לא מורשה. יפורטו סוגי המידע הסודי, מורשות הגישה, חריגים מוצדקים וחובות גילוי לפי דין. הסודיות לא תשמש למנוע פרסום ממצאים רק משום שאינם נוחים למי מהצדדים."},{"sectionId":"durationTermination","text":"תקופת ההתקשרות המוצעת: מיום {{effectiveDate}} ועד יום {{terminationDate}}, בכפוף להשלמת החתימות, האישורים ותנאי תחילת הפעילות. הארכה תוסדר בכתב ובחתימה הדדית ככל שהיא משנה את תנאי ההסכם.\n\nכל צד יוכל לסיים את שיתוף הפעולה בהודעה בכתב של {{terminationNoticeDays}} ימים מראש. במקרה של הפרה ייקבעו דרך ההודעה ותקופת התיקון, לפי העניין. במקרה של סיכון לפרטיות או לאבטחה ניתן יהיה להגביל מיד את הגישה הנוגעת לסיכון ולתעד את הסיבה והטיפול.\n\nעם הסיום יתועדו העבודה שבוצעה, תשלומים והתחייבויות קיימים, תוצרים להעברה ומידע לשמירה או למחיקה. תקופות השמירה, לרבות בגיבויים, ייקבעו בהתאם לדין, להסכמות ולאישורי המחקר; אין הבטחה למחיקה מיידית של כל עותק. המשך חובות סודיות, זכויות ותשלום יפורט במפורש, בלי ליצור חיובים חדשים מעצם הסיום."},{"sectionId":"annexes","text":"נוסח בסיס לפרסום: שותפת המחקר תוכל לפרסם ממצאים חיוביים, שליליים או שאינם חד משמעיים, תוך שמירת פרטיות, סודיות וזכויות רלוונטיות. טיוטת פרסום תועבר לעיון מוקדם של הצד האחר למשך {{publicationReviewPeriod}} {{publicationReviewUnit}}, לזיהוי חשש מסוים בתחומים אלה. העיון לא יקנה זכות לשנות ממצאים או לעכב פרסום ללא הגבלת זמן. היעדר הערות במועד יסיים את העיון המוקדם, בלי לגרוע מחובות החלות על הפרסום.\n\nמחברות, קרדיט והכרה ייקבעו לפי התרומה בפועל וכללי הגוף המפרסם. שם או לוגו של הצד האחר לא ישמשו להצהרת תמיכה מסחרית ללא אישור. שימוש שיווקי בממצאים יתאר במדויק את היקף המחקר ומגבלותיו.\n\nסעיף נוסף מוצע: הצדדים ינסו לפתור מחלוקת בפנייה מתועדת לאנשי הקשר ובהמשך לגורם מוסמך מכל צד, בתוך פרק זמן שיוסכם. סעיפים פרטניים ונספחים יקושרו לגרסה המתאימה; סדר העדיפות במקרה של סתירה ייקבע במפורש לפני החתימה."},{"sectionId":"reviewSigning","text":"לכל טיוטה יישמרו מספר גרסה, תאריך ושינויים. כל צד יוכל להציע תיקונים בתחומים המורשים לו; ההצעות לא ישנו את הנוסח שהצד האחר כבר אישר. לפני חתימה יאשרו שני הצדדים אותה גרסה סופית, לרבות הנספחים, והיא תוקפא לצורך החתימה.\n\nתהליך החתימה המתוכנן יכלול זיהוי החותמות ובדיקת סמכותן, הסכמה לחתום, תיעוד מועדים וגרסת המסמך, ראיות אימות, גיבוב לבדיקת שלמות ותיעוד הספק לפי השירות שנבחר. סוג החתימה יותאם לדין ולדרישות המוסד. פרטי הספק והבדיקות הנדרשות: {{signatureProvider}}; {{signatureVerification}}. אין במסמך זה אישור שספק פעיל או תהליך אימות כזה כבר זמינים ב BE GOOD.\n\nלאחר השלמת ואימות החתימות הנדרשות יימסר עותק חתום לשני הצדדים ויישמר עם ראיות החתימה בתיקייה מוגנת לפי הרשאות. הפעלת השותפות מותנית גם באישורי המחקר ובתנאי הגישה שנקבעו. אישור קריאת הסבר על קניין רוחני הוא אישור עיון בלבד ואינו מחליף חתימה.\n\nהסכם שנחתם וראיותיו יישמרו ללא שינוי. תיקון מאוחר יישמר כגרסה חדשה של נספח תיקון, עם אישור וחתימה של שני הצדדים וקישור להסכם המקורי. התחייבויות מחייבות יירשמו למעקב רק לאחר השלמת ההתקשרות, עם מקור הסעיף, האחראית, סכום אם יש, מועד, מצב וראיות ביצוע; הצעות ושינויים לא חתומים יישארו נפרדים."}],"ipExplanation":"אישור עיון בהסבר הקניין הרוחני הוא אישור קריאה בלבד ואינו מחליף חתימה על ההסכם.","mutualIPClause":"בעלות משותפת או רישיון הדדי יחולו רק על תוצר שזוהה והוסדר במפורש, בכפוף לדין ולזכויות הגורמים הרלוונטיים. אין ליטול זכויות של יוצרת, מוסד או צד שלישי בלי סמכות מתאימה. שינוי של הסדר זכויות שנחתם, העברת זכויות או רישיון בלעדי יוסדרו בתיקון מוסכם וחתום; תישמר גם כל זכות שאינה ניתנת לוויתור לפי הדין.","requiredFieldIds":["guidedVersion","title","ownerName","ownerEmail","ownerAddress","ownerSignatory","ownerAuthority","partnerName","partnerEmail","partnerAddress","partnerSignatory","partnerAuthority","studyTitle","purpose","objectives","researchQuestions","method","population","startDate","endDate","ownerResponsibilities","partnerResponsibilities","ipExplanationVersionId","ethicsApproval","effectiveDate","terminationDate","terminationNoticeDays","terminationTerms","postTermination","templateVersionId","ownerPartyKind","partnerPartyKind","ownerRegistration","partnerRegistration","ownerSignatoryRole","partnerSignatoryRole","institutionApproval","leadResearcher","leadResearcherRole","leadResearcherInstitution","agreementContacts","studyIdentifier","centralResearchQuestion","researchLimits","humanAIReview","freeTierTerms","supportChannels","supportDays","supportExtent","supportResponse","supportEscalation","consentConfiguration","confidentialScope","confidentialDuration","confidentialExceptions","breachNoticeTerms","suspensionTerms","handoverTerms","finalSettlement","publicationReviewPeriod","publicationReviewUnit","authorshipTerms","logoUseTerms","disputeContacts","disputePeriod","documentPrecedence","governingLaw","jurisdiction","liabilityTerms","insuranceTerms","finalVersionLabel","finalAnnexReferences","signerIdentityChecks","signatureProvider","signatureType","signaturePolicy","signatureVerification","signingConsentTerms","signedStorage","activationConditions","copyRecipients","annexAStatus","annexBStatus","annexCStatus","annexDStatus","annexEStatus","annexFStatus"]},"sections":[{"id":"parties","title":"פרטי הצדדים","paragraphs":[{"sourceParagraph":0,"status":"proposed","text":"הסכם זה מוצע בין {{ownerName}}, מספר זיהוי או רישום {{ownerRegistration}}, כתובת {{ownerAddress}}, דוא״ל להודעות {{ownerEmail}}, באמצעות {{ownerSignatory}}, {{ownerSignatoryRole}}, להלן ״בעלת המערכת״; לבין {{partnerName}}, מספר זיהוי או רישום {{partnerRegistration}}, כתובת {{partnerAddress}}, דוא״ל להודעות {{partnerEmail}}, באמצעות {{partnerSignatory}}, {{partnerSignatoryRole}}, להלן ״שותפת המחקר״."},{"sourceParagraph":1,"status":"proposed","text":"החוקרת האחראית מטעם שותפת המחקר תהיה {{leadResearcher}}, {{leadResearcherRole}}, {{leadResearcherInstitution}}. כל צד יפעל בתחום סמכותו ויקבל את אישורי המוסד או הגורמים מטעמו הדרושים להתקשרות ולביצוע חלקו במחקר. הקשר המקצועי יתנהל באמצעות אנשי הקשר המפורטים בנספח א."}],"complete":["לקבוע מי הצד המתקשר בפועל: החוקרת אישית, מוסד, או שניהם; להשלים פרטי זיהוי, כתובות, אנשי קשר והוכחת סמכות חתימה לפי הצורך."],"guidance":["חוקרת העובדת במוסד אינה בהכרח מוסמכת להתחייב בשמו או להקנות זכויות בתוצריו. יש להפריד בין החוקרת המובילה לבין הגורם שמתחייב בהסכם."]},{"id":"study","title":"המחקר ומטרותיו","paragraphs":[{"sourceParagraph":0,"status":"proposed","text":"מזהה המחקר: {{studyIdentifier}}. שם המחקר: {{studyTitle}}. מטרת שיתוף הפעולה המוצעת היא לבחון את השימוש בכלי BE GOOD בהקשר חינוכי מוגדר, את התאמתם לצורכי המשתמשות והמשתמשים ואת התובנות העולות מהשימוש בהם. שאלת המחקר המרכזית תהיה: {{centralResearchQuestion}}."},{"sourceParagraph":1,"status":"proposed","text":"תוכנית המחקר בנספח א תפרט את שאלות המחקר, השיטה, המסגרות החינוכיות, אוכלוסיית המחקר, דרך הגיוס, כלי המדידה, מועדי הפעילות והתוצרים."},{"sourceParagraph":2,"status":"proposed","text":"חלוקת האחריות המוצעת: שותפת המחקר תוביל את תכנון המחקר, האישורים, הגיוס, ההסכמות והניתוח, לפי חלוקה שתיקבע בנספח א. בעלת המערכת תספק את הכלים, ההדרכה והתמיכה שהוגדרו במפורש. אין התחייבות לתוצאה מחקרית מסוימת או להוכחת השפעה; המסקנות יתבססו על הנתונים ועל מגבלות המחקר."}],"complete":["שאלות ושיטת מחקר, אוכלוסייה והיקף, מוסדות משתתפים, אחראית לכל שלב, מועדים ותוצרים כגון דוח, מאמר או המלצות. לציין התאמות נדרשות לבית הספר ודרך בדיקת התאמתן."],"guidance":["לנסח מטרה ממוקדת שאפשר לבדוק, ולציין מה המחקר אינו יכול להסיק. לקבוע מי אחראית להתאמה לבית הספר, להדרכה ולמשוב מהשטח."]},{"id":"tools","title":"כלים, שאלונים והרשאות","paragraphs":[{"sourceParagraph":0,"status":"proposed","text":"לשותפת המחקר תינתן הרשאת שימוש אישית ומוגבלת בכלי BE GOOD שיפורטו בנספח ב, לצורכי המחקר המוגדר ולמשך התקופה שתאושר. לכל כלי יירשמו שם וגרסה, המשתמשות המורשות, הפעולות המותרות, היקף השימוש, הגישה לנתונים והאפשרות לייצוא."},{"sourceParagraph":1,"status":"proposed","text":"הגישה תוגבל למחקר ולסביבת השותפות שהוקצו לכל משתמשת. אין להעביר פרטי כניסה או לתת גישה לאדם נוסף ללא הרשאה נפרדת. שימוש במחקר אחר, בהדרכה חיצונית או בפעילות מסחרית יוסדר מראש לפי היקף ההרשאה והזכויות הרלוונטיות."},{"sourceParagraph":2,"status":"proposed","text":"שאלונים, מדדים וחומרים חיצוניים ישמשו בהתאם לתנאי השימוש החלים עליהם. הרשאת שימוש במערכת אינה כוללת כשלעצמה מסירת קוד מקור או הרשאת ניהול כללית. אחריות לבדיקה מקצועית של תוצרי AI לפני שימוש חינוכי תוגדר בתוכנית העבודה."}],"complete":["לכל כלי או שאלון: שם, מקור וגרסה; למי יש גישה; האם מותר לצפות, להזין, לערוך, לנתח ולייצא; מכסות, מועדי התחלה וסיום והדרכה נדרשת."],"guidance":["לרשום הרשאה מעשית, למשל ״צפייה בדוחות מצרפיים של מחקר זה״. אין להקצות גישה למידע אישי רק משום שלמשתמשת יש תפקיד ניהולי."]},{"id":"contributions","title":"תרומות הצדדים","paragraphs":[{"sourceParagraph":0,"status":"proposed","text":"תרומות הצדדים יפורטו בנספח ד: ידע מדעי, תכנון ושיטות, שאלונים ומדידות, תוכן חינוכי, טכנולוגיה, מימון, שירות מקצועי או תרומה אחרת. לכל תרומה יירשמו הגורם התורם, התיאור, התוצר, אבני הדרך, מועד ההשלמה, אופן בדיקת הביצוע וההכרה או התמורה שהתבקשו והוסכמו."},{"sourceParagraph":1,"status":"proposed","text":"רישום תרומה הוא תחילה הצעה בלבד. אין בהגשתה או באישור פעילות מחקרית כדי ליצור לבדם התחייבות לתשלום, לפיתוח, לשילוב ב BE GOOD, להעברת קניין רוחני, לחלוקת הכנסות או לבלעדיות. התחייבות תירשם כמוסכמת רק לאחר שהוסדרה בתנאים שהצדדים אישרו והשלימו עבורם את הליך ההתקשרות הנדרש."},{"sourceParagraph":2,"status":"proposed","text":"הנוסח המקורי, הערות הצדדים, התנאים שהוסכמו, שינויים וראיות לביצוע יישמרו כרשומות נפרדות ומקושרות. מסמך תרומה ייחשף רק למי שהורשתה לכך. זכויות בתוכן קודם או בתוצר חדש יוסדרו גם לפי סעיף 8 ונספח ו."}],"complete":["רשומת בסיס לנספח ד: מזהה תרומה [להשלמה]; תורמת ומוסד [להשלמה]; תוצר [להשלמה]; אבני דרך ומועדים [להשלמה]; התחייבות בעלת המערכת [להשלמה]; קרדיט, תשלום או זכויות מבוקשים [להשלמה]; התנאים שהוסכמו והמסמך המאשר [להשלמה]."],"guidance":["להבחין בין בקשה, תנאי שהוסכם ותרומה שכבר בוצעה. מימון או משוב אינם מקנים כשלעצמם בעלות בנכסי BE GOOD."]},{"id":"sharedExpenses","title":"הוצאות הפעלה משותפות","paragraphs":[{"sourceParagraph":0,"status":"proposed","text":"הוצאות הפעלה לצורך המחקר יפורטו בתקציב שבנספח ג. אפשר לכלול, לפי הצורך, שימוש בשירותי AI, אחסון, רישוי, חתימה אלקטרונית והוצאות תפעול נוספות. לכל פריט ייקבעו מטרתו, בסיס החישוב, מטבע, מסים ככל שחלים, תקרת הוצאה, חלוקת התשלום והגורם המאשר."},{"sourceParagraph":1,"status":"proposed","text":"הוצאה, חריגה או שירות בתשלום לא יופעלו על חשבון הצד האחר בלי אישור מוקדם ומתועד של הגורם המוסמך ובהתאם לתקציב המוסכם. אופן ההתחשבנות, האסמכתאות ומועד התשלום יפורטו בנספח ג. אין הנחה שהעלויות מתחלקות בחלקים שווים."},{"sourceParagraph":2,"status":"proposed","text":"התקציב יבחין בין סכום משוער, תקרה מאושרת והוצאה בפועל. שינוי היוצר התחייבות חוזית חדשה יועבר להסכמה ולחתימה על תיקון לפי סעיף 12."}],"complete":["לכל הוצאה: השירות והצורך [להשלמה]; הערכת עלות ותקרה [להשלמה]; מטבע ומסים [להשלמה]; חלקו של כל צד [להשלמה]; מי משלם בפועל ולמי [להשלמה]; אישור, אסמכתאות ומועד התחשבנות [להשלמה]."],"guidance":["אם השימוש אמור להישאר במסלול חינמי, לכתוב זאת במפורש ולקבוע מה עושים בהגעה למכסה. שדה תקציב ריק אינו אישור להוצאה."]},{"id":"professionalFees","title":"שכר ושירותים מקצועיים","paragraphs":[{"sourceParagraph":0,"status":"proposed","text":"תשלום עבור שירות מקצועי יוסדר בנפרד מהוצאות ההפעלה. לכל שירות יוגדרו נותנת השירות, מקבלת השירות, תכולת העבודה, התוצר, היקף שעות או מחיר קבוע, סכום ומטבע, מסים ככל שחלים, מועדים ותנאי קבלת התוצר."},{"sourceParagraph":1,"status":"proposed","text":"התשלום יבוצע בהתאם לאבן הדרך או לתנאי שנקבעו בנספח ג וכנגד המסמכים הנדרשים לפי העניין. עבודה נוספת מעבר להיקף המוסכם תחייב הסכמה מוקדמת על תכולה, מחיר ומועד. ההסכם יפרט גם כיצד מתחשבנים על עבודה מאושרת שכבר בוצעה במקרה של סיום מוקדם."},{"sourceParagraph":2,"status":"proposed","text":"אין להסיק מכך ששדה תשלום טרם מולא שהשירות ניתן ללא תמורה. אם הצדדים מבקשים להסכים על תרומה ללא תשלום, יש לציין זאת במפורש לצד היקף התרומה והקרדיט שסוכם."}],"complete":["שירות ותוצר [להשלמה]; נותנת ומקבלת השירות [להשלמה]; שיטת תמחור וסכום [להשלמה]; תקרת שעות אם רלוונטית [להשלמה]; מסים, מסמכי חיוב, תנאי ומועד תשלום [להשלמה]; טיפול בעבודה חלקית [להשלמה]."],"guidance":["לבחור תמחור שמתאים לעבודה: לפי תוצר, לפי שעה או שילוב מוגדר. לא להשאיר ניסוח כגון ״תמיכה לפי הצורך״ בלי היקף ומנגנון אישור."]},{"id":"development","title":"פיתוח, התאמות ותמיכה","paragraphs":[{"sourceParagraph":0,"status":"proposed","text":"עבודות פיתוח והתאמה לבית הספר או למחקר ייקבעו בתוכנית עבודה נפרדת. לכל משימה יוגדרו הצורך החינוכי, המשתמשות, השינוי המבוקש, תוצר מדיד, מי מבצעת, עלות אם יש, אבני דרך, סביבת בדיקה ותנאי קבלה. הדרכה, התאמת תוכן ושינוי תוכנה יתוארו בנפרד לפי הצורך."},{"sourceParagraph":1,"status":"proposed","text":"פיתוח שלא נכלל בתוכנית המאושרת יישאר בגדר בקשה עד להסכמה על היקפו, משאביו, לוחות הזמנים והזכויות בתוצר. אין התחייבות אוטומטית לפיתוח ללא תשלום או לשילוב כל הצעה בגרסה הכללית של BE GOOD. שינוי באתר החי יחייב את אישור בעלת המערכת ובדיקות מתאימות."},{"sourceParagraph":2,"status":"proposed","text":"התמיכה תינתן בערוצים, בימים ובהיקף שייקבעו. זמני מענה, תחזוקה והסלמה יוגדרו במפורש; אין התחייבות לזמינות רציפה אם לא סוכמה. שימוש חינוכי בתוצרי AI מחייב שיקול דעת מקצועי ובדיקה אנושית בהתאם לתפקיד."}],"complete":["לכל משימת התאמה: בית הספר והצורך [להשלמה]; תוצר ותנאי קבלה [להשלמה]; מבצעת, תקציב ומועד [להשלמה]; הדרכה ובדיקת שימושיות [להשלמה]; תחזוקה ותמיכה [להשלמה]; הסדר הזכויות בתוצר [להשלמה]."],"guidance":["להתחיל בהתאמה מצומצמת ולבדוק אותה עם המשתמשות לפני הרחבה. להחליט מראש מי מאשרת שההתאמה עונה על הצורך ומי אחראית להמשך התחזוקה."]},{"id":"mutualIP","title":"בעלות בנכסי BE GOOD","paragraphs":[{"sourceParagraph":0,"status":"owner_approved","text":"בעלת המערכת מצהירה כי פיתחה את קוד BE GOOD ואת תכניה המקוריים. הספרות המדעית המוזכרת שימשה ללמידה ולביסוס הפיתוח, ללא העתקת טקסטים, טבלאות או איורים ממנה. זכויותיה בקוד ובתכנים המקוריים יישארו בידיה."},{"sourceParagraph":1,"status":"owner_approved","text":"הרשאה להשתתף במחקר אינה מקנה כשלעצמה בעלות בנכסי המערכת הקיימים. זכויות בתוצרים חדשים של שיתוף הפעולה יוסדרו בנפרד ובמפורש."},{"sourceParagraph":2,"status":"proposed","text":"הזכויות הקודמות של שותפת המחקר, של המוסד ושל צדדים שלישיים יישמרו בידי בעלי הזכויות. לפני יצירת תוצר חדש יירשמו בנספח ו היוצרות ובעלי הזכויות, הבעלות המוסכמת, רישיון השימוש, אפשרות שינוי והפצה, שימוש מסחרי, פרסום וקרדיט. אין בטיוטה זו קביעה שקיימים כבר נכסים משותפים."},{"sourceParagraph":3,"status":"proposed","text":"בעלות משותפת או רישיון הדדי יחולו רק על תוצר שזוהה והוסדר במפורש, בכפוף לדין ולזכויות הגורמים הרלוונטיים. אין ליטול זכויות של יוצרת, מוסד או צד שלישי בלי סמכות מתאימה. שינוי של הסדר זכויות שנחתם, העברת זכויות או רישיון בלעדי יוסדרו בתיקון מוסכם וחתום; תישמר גם כל זכות שאינה ניתנת לוויתור לפי הדין."}],"complete":["נספח ו: רשימת נכסי BE GOOD הקודמים ותיאורם; נכסים קודמים של השותפה או המוסד; לכל תוצר חדש — תיאור, יוצרות, בעלות או רישיון, תחומים מותרים, תקופה, תמורה אם יש, פרסום וקרדיט."],"guidance":["הנוסח המוצע מפריד בין מה שפיתחת עד כה לבין מה שעשוי להיווצר בעתיד. אין להכריז שכל תוצר עתידי שלך, או משותף, בלי לבדוק מי יצרה אותו ואילו זכויות חלות עליו."]},{"id":"privacyEthics","title":"פרטיות ואתיקה","paragraphs":[{"sourceParagraph":0,"status":"proposed","text":"ההשתתפות במחקר תהיה מרצון ובהתאם להליך ההסכמה ולאישורים שייקבעו למחקר. ההחלטה להשתתף במחקר תופרד מהשימוש המקצועי ב BE GOOD, ולא תהווה תנאי לקבלת שירות שאינו מחייב השתתפות במחקר. לפני איסוף נתונים יושלמו האישורים הנדרשים מהמוסד, מהמסגרת החינוכית ומגורמי האתיקה הרלוונטיים."},{"sourceParagraph":1,"status":"proposed","text":"נספח ה יפרט את סוגי המידע, מטרות העיבוד, תפקידי הצדדים, ההרשאות, ספקים נוספים, מקום האחסון, תקופות שמירה ומחיקה והליך פרישה מהמחקר. ההודעה למשתתפים תסביר את הבחירה להשתתף ואת זכויותיהם, לרבות מגבלות על הסרה לאחר אִגום בלתי הפיך, ככל שרלוונטי."},{"sourceParagraph":2,"status":"proposed","text":"כל צד יקבל רק את המידע הנדרש לתפקידו ולמטרה המותרת. בעלות על המערכת אינה מעניקה כשלעצמה הרשאה לעיין במידע אישי של משתתפים. ייקבעו הפרדת הרשאות, הגנה על מסמכים, טיפול בבקשות ובאירועים, ואחראית לפניות. מידע אישי לא יועבר לספק AI חיצוני לפני שהוסדרו ונבדקו תנאי העיבוד והבסיס המתאים להעברה."},{"sourceParagraph":3,"status":"proposed","text":"מידע סודי שיימסר לצורך השותפות ישמש רק למטרה שהותרה ויוגן מפני גילוי לא מורשה. יפורטו סוגי המידע הסודי, מורשות הגישה, חריגים מוצדקים וחובות גילוי לפי דין. הסודיות לא תשמש למנוע פרסום ממצאים רק משום שאינם נוחים למי מהצדדים."}],"complete":["מספרי אישורי אתיקה והיתרים לפי הצורך; הסכמות למשתתפים ולקטינים אם רלוונטי; אחראיות לעיבוד ולאבטחה; סוגי מידע; הרשאות וספקים; שמירה, גיבויים ומחיקה; טיפול באירועים ופרטי פנייה; היקף הסודיות ומשך החובה."],"guidance":["להעדיף מידע מצרפי או מצומצם כשדי בו למחקר. אין להתחיל איסוף מידע רק מפני שהסכם השותפות נחתם; יש לבדוק את התנאים והאישורים למחקר המסוים."]},{"id":"durationTermination","title":"תקופה וסיום","paragraphs":[{"sourceParagraph":0,"status":"proposed","text":"תקופת ההתקשרות המוצעת: מיום {{effectiveDate}} ועד יום {{terminationDate}}, בכפוף להשלמת החתימות, האישורים ותנאי תחילת הפעילות. הארכה תוסדר בכתב ובחתימה הדדית ככל שהיא משנה את תנאי ההסכם."},{"sourceParagraph":1,"status":"proposed","text":"כל צד יוכל לסיים את שיתוף הפעולה בהודעה בכתב של {{terminationNoticeDays}} ימים מראש. במקרה של הפרה ייקבעו דרך ההודעה ותקופת התיקון, לפי העניין. במקרה של סיכון לפרטיות או לאבטחה ניתן יהיה להגביל מיד את הגישה הנוגעת לסיכון ולתעד את הסיבה והטיפול."},{"sourceParagraph":2,"status":"proposed","text":"עם הסיום יתועדו העבודה שבוצעה, תשלומים והתחייבויות קיימים, תוצרים להעברה ומידע לשמירה או למחיקה. תקופות השמירה, לרבות בגיבויים, ייקבעו בהתאם לדין, להסכמות ולאישורי המחקר; אין הבטחה למחיקה מיידית של כל עותק. המשך חובות סודיות, זכויות ותשלום יפורט במפורש, בלי ליצור חיובים חדשים מעצם הסיום."}],"complete":["תאריכי התחלה וסיום; ימי הודעה מוקדמת; הפרות ותקופת תיקון; תנאי עצירה; אחריות להעברת תוצרים ולסגירת הרשאות; התחשבנות סופית; חובות שנמשכות לאחר הסיום."],"guidance":["אפשר לדון בהודעה מוקדמת של 30 ימים כנקודת מוצא בלבד. יש להתאים את התקופה למחקר ולצורכי המשתתפים; מספר זה טרם אושר."]},{"id":"annexes","title":"נספחים, פרסום וסעיפים נוספים","paragraphs":[{"sourceParagraph":0,"status":"proposed","text":""},{"sourceParagraph":1,"status":"proposed","text":"נוסח בסיס לפרסום: שותפת המחקר תוכל לפרסם ממצאים חיוביים, שליליים או שאינם חד משמעיים, תוך שמירת פרטיות, סודיות וזכויות רלוונטיות. טיוטת פרסום תועבר לעיון מוקדם של הצד האחר למשך {{publicationReviewPeriod}} {{publicationReviewUnit}}, לזיהוי חשש מסוים בתחומים אלה. העיון לא יקנה זכות לשנות ממצאים או לעכב פרסום ללא הגבלת זמן. היעדר הערות במועד יסיים את העיון המוקדם, בלי לגרוע מחובות החלות על הפרסום."},{"sourceParagraph":2,"status":"proposed","text":"מחברות, קרדיט והכרה ייקבעו לפי התרומה בפועל וכללי הגוף המפרסם. שם או לוגו של הצד האחר לא ישמשו להצהרת תמיכה מסחרית ללא אישור. שימוש שיווקי בממצאים יתאר במדויק את היקף המחקר ומגבלותיו."},{"sourceParagraph":3,"status":"proposed","text":"סעיף נוסף מוצע: הצדדים ינסו לפתור מחלוקת בפנייה מתועדת לאנשי הקשר ובהמשך לגורם מוסמך מכל צד, בתוך פרק זמן שיוסכם. סעיפים פרטניים ונספחים יקושרו לגרסה המתאימה; סדר העדיפות במקרה של סתירה ייקבע במפורש לפני החתימה."}],"complete":["להכין ולצרף את הנספחים שבאמת נדרשים; לקבוע חלון עיון בפרסום, קרדיט ואנשי קשר; להשלים סדר עדיפות בין מסמכים, מנגנון יישוב מחלוקת, דין וסמכות שיפוט, והסדרי אחריות וביטוח ככל שנדרשים."],"guidance":["אפשר לדון ב 21 ימי עסקים לעיון בפרסום כבסיס בלבד. אחריות, פיצוי, ביטוח וסמכות שיפוט מצריכים החלטה מפורשת; לא נוספה כאן התחייבות פתוחה או ויתור גורף על זכויות."]},{"id":"reviewSigning","title":"עיון, אישור וחתימה","paragraphs":[{"sourceParagraph":0,"status":"proposed","text":"לכל טיוטה יישמרו מספר גרסה, תאריך ושינויים. כל צד יוכל להציע תיקונים בתחומים המורשים לו; ההצעות לא ישנו את הנוסח שהצד האחר כבר אישר. לפני חתימה יאשרו שני הצדדים אותה גרסה סופית, לרבות הנספחים, והיא תוקפא לצורך החתימה."},{"sourceParagraph":1,"status":"proposed","text":"תהליך החתימה המתוכנן יכלול זיהוי החותמות ובדיקת סמכותן, הסכמה לחתום, תיעוד מועדים וגרסת המסמך, ראיות אימות, גיבוב לבדיקת שלמות ותיעוד הספק לפי השירות שנבחר. סוג החתימה יותאם לדין ולדרישות המוסד. פרטי הספק והבדיקות הנדרשות: {{signatureProvider}}; {{signatureVerification}}. אין במסמך זה אישור שספק פעיל או תהליך אימות כזה כבר זמינים ב BE GOOD."},{"sourceParagraph":2,"status":"proposed","text":"לאחר השלמת ואימות החתימות הנדרשות יימסר עותק חתום לשני הצדדים ויישמר עם ראיות החתימה בתיקייה מוגנת לפי הרשאות. הפעלת השותפות מותנית גם באישורי המחקר ובתנאי הגישה שנקבעו. אישור קריאת הסבר על קניין רוחני הוא אישור עיון בלבד ואינו מחליף חתימה."},{"sourceParagraph":3,"status":"proposed","text":"הסכם שנחתם וראיותיו יישמרו ללא שינוי. תיקון מאוחר יישמר כגרסה חדשה של נספח תיקון, עם אישור וחתימה של שני הצדדים וקישור להסכם המקורי. התחייבויות מחייבות יירשמו למעקב רק לאחר השלמת ההתקשרות, עם מקור הסעיף, האחראית, סכום אם יש, מועד, מצב וראיות ביצוע; הצעות ושינויים לא חתומים יישארו נפרדים."}],"complete":["מספר הגרסה הסופית והנספחים; זהות וסמכות כל חותמת; ספק וסוג חתימה; ראיות ואופן אימות; מקום שמירה והרשאות; כתובות למסירת העותק; תנאי תחילת הפעילות."],"guidance":["חתימה במערכת תחייב שירות פעיל ותהליך בדיקה שהושלם. אין לסמן טיוטה זו כהסכם חתום או להפעיל התחייבות רק בעקבות אישור במסך."]}],"bodyPlaceholders":[{"sectionId":"parties","paragraphIndex":0,"occurrence":0,"marker":"[להשלמה: השם המשפטי של בעלת BE GOOD או של הישות המתקשרת]","fieldId":"ownerName","fieldIds":["ownerName"]},{"sectionId":"parties","paragraphIndex":0,"occurrence":1,"marker":"[להשלמה]","fieldId":"ownerRegistration","fieldIds":["ownerRegistration"]},{"sectionId":"parties","paragraphIndex":0,"occurrence":2,"marker":"[להשלמה]","fieldId":"ownerAddress","fieldIds":["own