ate"]},{"sectionId":"durationTermination","paragraphIndex":1,"occurrence":0,"marker":"[להשלמה: מספר ימים מוסכם]","fieldId":"terminationNoticeDays","fieldIds":["terminationNoticeDays"]},{"sectionId":"annexes","paragraphIndex":1,"occurrence":0,"marker":"[להשלמה: תקופה מוסכמת ומוגבלת]","fieldId":"publicationReviewPeriod","fieldIds":["publicationReviewPeriod","publicationReviewUnit"]},{"sectionId":"reviewSigning","paragraphIndex":1,"occurrence":0,"marker":"[להשלמה]","fieldId":"signatureProvider","fieldIds":["signatureProvider","signatureVerification"]}],"decisions":[{"sectionId":"parties","kind":"complete","index":0,"text":"לקבוע מי הצד המתקשר בפועל: החוקרת אישית, מוסד, או שניהם; להשלים פרטי זיהוי, כתובות, אנשי קשר והוכחת סמכות חתימה לפי הצורך.","fieldPaths":["title","ownerName","ownerInstitution","ownerEmail","ownerAddress","ownerSignatory","ownerAuthority","partnerName","partnerInstitution","partnerEmail","partnerAddress","partnerSignatory","partnerAuthority","guidedVersion","ownerPartyKind","partnerPartyKind","ownerRegistration","partnerRegistration","ownerSignatoryRole","partnerSignatoryRole","institutionApproval","leadResearcher","leadResearcherRole","leadResearcherInstitution","agreementContacts","agreementContacts[].name","agreementContacts[].role","agreementContacts[].email"]},{"sectionId":"parties","kind":"guidance","index":0,"text":"חוקרת העובדת במוסד אינה בהכרח מוסמכת להתחייב בשמו או להקנות זכויות בתוצריו. יש להפריד בין החוקרת המובילה לבין הגורם שמתחייב בהסכם.","fieldPaths":["title","ownerName","ownerInstitution","ownerEmail","ownerAddress","ownerSignatory","ownerAuthority","partnerName","partnerInstitution","partnerEmail","partnerAddress","partnerSignatory","partnerAuthority","guidedVersion","ownerPartyKind","partnerPartyKind","ownerRegistration","partnerRegistration","ownerSignatoryRole","partnerSignatoryRole","institutionApproval","leadResearcher","leadResearcherRole","leadResearcherInstitution","agreementContacts","agreementContacts[].name","agreementCont