CREATE TABLE research_private.agreement_preparations(id uuid PRIMARY KEY DEFAULT pg_catalog.gen_random_uuid(),study_id uuid NOT NULL,partner_id uuid NOT NULL,record_id uuid NOT NULL,version_id uuid NOT NULL UNIQUE,initial_receipt_id uuid REFERENCES research_private.agreement_preparations(id),snapshot jsonb NOT NULL,field_sources jsonb NOT NULL,overrides jsonb NOT NULL DEFAULT '[]',source_hash text NOT NULL,created_by text NOT NULL,created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(study_id,partner_id,record_id,version_id) REFERENCES research_private.partnership_versions(study_id,partner_id,record_id,id));
CREATE TABLE research_private.processing_policies(id uuid PRIMARY KEY DEFAULT pg_catalog.gen_random_uuid(),study_id uuid NOT NULL REFERENCES research_private.studies(id),partner_id uuid NOT NULL REFERENCES research_private.partnership_partners(id),revision integer NOT NULL,policy jsonb NOT NULL,policy_hash text NOT NULL,restriction_hash text NOT NULL,created_by text NOT NULL,created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(study_id,partner_id,revision));
CREATE TABLE research_private.processing_policy_approvals(policy_id uuid PRIMARY KEY REFERENCES research_private.processing_policies(id),approved_by text NOT NULL,created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP);
DO $tables$ DECLARE t text; BEGIN
 FOR t IN SELECT pg_catalog.unnest(ARRAY['agreement_preparations','processing_policies','processing_policy_approvals']) LOOP
  EXECUTE pg_catalog.format('ALTER TABLE research_private.%I OWNER TO research_table_owner',t);
  EXECUTE pg_catalog.format('ALTER TABLE research_private.%I ENABLE ROW LEVEL SECURITY',t);
  EXECUTE pg_catalog.format('ALTER TABLE research_private.%I FORCE ROW LEVEL SECURITY',t);
  EXECUTE pg_catalog.format('REVOKE ALL ON research_private.%I FROM PUBLIC,anon,authenticated,service_role',t);
  EXECUTE pg_catalog.format('GRANT SELECT,INSERT ON research_private.%I TO research_worker',t);
  EXECUTE pg_catalog.format('CREATE TRIGGER guided_immutable BEFORE UPDATE OR DELETE OR TRUNCATE ON research_private.%I FOR EACH STATEMENT EXECUTE FUNCTION research_private.immutable()',t);
 END LOOP;
END $tables$;
CREATE POLICY guided_scope ON research_private.agreement_preparations FOR SELECT TO research_worker USING(research_private.partnership_scope(study_id,partner_id));
CREATE POLICY guided_scope_insert ON research_private.agreement_preparations FOR INSERT TO research_worker WITH CHECK(research_private.partnership_scope(study_id,partner_id) AND pg_catalog.current_setting('research.signing',true) IS DISTINCT FROM 'true');
CREATE POLICY owner_policy ON research_private.processing_policies TO research_worker USING(pg_catalog.current_setting('research.owner',true)='true') WITH CHECK(pg_catalog.current_setting('research.owner',true)='true');
CREATE POLICY owner_policy ON research_private.processing_policy_approvals TO research_worker USING(pg_catalog.current_setting('research.owner',true)='true') WITH CHECK(pg_catalog.current_setting('research.owner',true)='true');

CREATE FUNCTION research_private.guided_auth(raw_token text,sid uuid,pid uuid,owner_only boolean DEFAULT false,retained_owner_read boolean DEFAULT false) RETURNS jsonb LANGUAGE plpgsql SET search_path='' AS $f$
DECLARE a jsonb;p research_private.partnership_partners;s research_private.studies;BEGIN
 PERFORM research_private.intake_reset();a:=research_private.auth(raw_token);
 IF COALESCE((a->>'internal')::boolean,false) OR owner_only AND a->>'owner' IS DISTINCT FROM 'true' THEN PERFORM research_private.fail('unauthorized');END IF;
 PERFORM pg_catalog.set_config('research.actor',a->>'actor',true);PERFORM pg_catalog.set_config('research.owner',COALESCE(a->>'owner','false'),true);PERFORM pg_catalog.set_config('research.study',sid::text,true);PERFORM pg_catalog.set_config('research.partner',pid::text,true);
 SELECT * INTO s FROM research_private.studies WHERE id=sid FOR SHARE;SELECT * INTO p FROM research_private.partnership_partners WHERE id=pid FOR SHARE;
 IF s.id IS NULL OR p.id IS NULL OR a->>'owner' IS DISTINCT FROM 'true' AND p.actor_ref IS DISTINCT FROM a->>'actor' THEN PERFORM research_private.fail('not_found');END IF;
 IF NOT(a->>'owner'='true' AND retained_owner_read) AND NOT research_private.partnership_live_member(sid,p.actor_ref) THEN PERFORM research_private.fail('not_found');END IF;
 PERFORM pg_catalog.set_config('research.permissions',COALESCE((SELECT pg_catalog.to_jsonb(m.permissions)::text FROM research_private.memberships m WHERE m.study_id=sid AND m.actor_ref=p.actor_ref),'[]'),true);
 RETURN a;
END $f$;
CREATE FUNCTION research_private.guided_receipt(p research_private.agreement_preparations) RETURNS jsonb LANGUAGE sql STABLE SET search_path='' AS $f$
 SELECT CASE WHEN p.id IS NULL THEN NULL ELSE pg_catalog.jsonb_build_object('id',p.id,'initialReceiptId',COALESCE(p.initial_receipt_id,p.id),'recordId',p.record_id,'versionId',p.version_id,'snapshot',p.snapshot,'fieldSources',p.field_sources,'overrides',p.overrides,'sourceHash',p.source_hash,'createdAt',p.created_at) END $f$;
CREATE FUNCTION research_private.guided_restrictions(sid uuid) RETURNS text LANGUAGE sql STABLE SET search_path='' AS $f$
 SELECT research_private.partnership_hash(pg_catalog.jsonb_build_object('config',s.config,'consent',(SELECT pg_catalog.jsonb_build_object('id',v.id,'definition',v.definition,'published',EXISTS(SELECT 1 FROM research_private.form_publications fp WHERE fp.study_id=sid AND fp.version_id=v.id)) FROM research_private.form_versions v WHERE v.study_id=sid AND v.id=(s.config->>'consentVersionId')::uuid))) FROM research_private.studies s WHERE s.id=sid $f$;
CREATE FUNCTION research_private.guided_sources(sid uuid,pid uuid) RETURNS jsonb LANGUAGE sql STABLE SET search_path='' AS $f$
 SELECT pg_catalog.jsonb_build_object('profile',pg_catalog.jsonb_build_object('id',p.id,'revision',p.revision,'data',p.profile),'study',pg_catalog.jsonb_build_object('id',s.id,'revision',s.revision,'config',s.config,'versions',research_private.versions()),'currentGrants',pg_catalog.to_jsonb(m.permissions),'applications',COALESCE((SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('recordId',r.id,'versionId',v.id,'revision',r.revision,'status',r.status,'hash',v.content_hash,'data',v.data) ORDER BY r.created_at,r.id) FROM research_private.partnership_records r JOIN research_private.partnership_versions v ON v.id=r.head_version_id WHERE r.study_id=sid AND r.partner_id=pid AND r.kind='application'),'[]'),'budgets',COALESCE((SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('recordId',r.id,'versionId',v.id,'revision',r.revision,'hash',v.content_hash,'data',v.data) ORDER BY r.created_at,r.id) FROM research_private.partnership_records r JOIN research_private.partnership_versions v ON v.id=r.approved_version_id AND v.id=r.head_version_id WHERE r.study_id=sid AND r.partner_id=pid AND r.kind='budget' AND r.status='approved'),'[]'),'contributions',COALESCE((SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('recordId',r.id,'versionId',v.id,'revision',r.revision,'hash',v.content_hash,'data',v.data,'approvedTerms',(SELECT rv.approved_terms FROM research_private.partnership_reviews rv WHERE rv.version_id=v.id AND rv.decision='approved' ORDER BY rv.created_at DESC LIMIT 1)) ORDER BY r.created_at,r.id) FROM research_private.partnership_records r JOIN research_private.partnership_versions v ON v.id=r.approved_version_id AND v.id=r.head_version_id WHERE r.study_id=sid AND r.partner_id=pid AND r.kind='contribution' AND r.status IN ('approved','completed')),'[]'),'forms',COALESCE((SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('id',fv.id,'kind',fv.kind,'hash',research_private.partnership_hash(fv.definition),'title',fv.definition->'title','published',EXISTS(SELECT 1 FROM research_private.form_publications fp WHERE fp.study_id=sid AND fp.version_id=fv.id)) ORDER BY fv.created_at,fv.id) FROM research_private.form_versions fv WHERE fv.study_id=sid AND (fv.id=(s.config->>'consentVersionId')::uuid OR COALESCE(s.config->'instrumentVersionIds','[]') ? fv.id::text)),'[]'),'restrictionHash',research_private.guided_restrictions(sid),'catalogHash',research_private.guided_catalog()#>>'{source,sha256}') FROM research_private.studies s JOIN research_private.partnership_partners p ON p.id=pid JOIN research_private.memberships m ON m.study_id=s.id AND m.actor_ref=p.actor_ref WHERE s.id=sid $f$;

-- Source selections are references only. Values, revisions and approval facts are
-- re-read here under the current scope and cannot be asserted in agreement JSON.
CREATE FUNCTION research_private.guided_lock_sources(sid uuid,pid uuid) RETURNS void LANGUAGE plpgsql SET search_path='' AS $f$
BEGIN PERFORM 1 FROM research_private.partnership_records r WHERE r.study_id=sid AND r.partner_id=pid AND r.kind IN ('application','budget','contribution') ORDER BY r.id FOR SHARE;END $f$;
CREATE FUNCTION research_private.guided_candidate(src jsonb,selection jsonb) RETURNS jsonb LANGUAGE plpgsql SET search_path='' AS $f$
DECLARE app jsonb:='{}';budgets jsonb:='[]';contributions jsonb:='[]';item jsonb;d jsonb;fields jsonb:='{}';selected jsonb;key text;target text;map jsonb;annex jsonb;ref jsonb;BEGIN
 IF selection ? 'applicationVersionId' THEN SELECT x INTO app FROM pg_catalog.jsonb_array_elements(src->'applications') x WHERE x->>'versionId'=selection->>'applicationVersionId';IF app IS NULL THEN PERFORM research_private.fail('not_found');END IF;
 ELSIF pg_catalog.jsonb_array_length(src->'applications')>1 THEN PERFORM research_private.fail('conflict');ELSE app:=COALESCE(src#>'{applications,0}','{}');END IF;
 FOREACH key IN ARRAY ARRAY['budgets','contributions'] LOOP
  target:=CASE key WHEN 'budgets' THEN 'budgetVersionIds' ELSE 'contributionVersionIds' END;
  IF selection ? target THEN
   FOR item IN SELECT pg_catalog.jsonb_array_elements(selection->target) LOOP
    SELECT x INTO selected FROM pg_catalog.jsonb_array_elements(src->key) x WHERE x->'versionId'=item;
    IF selected IS NULL THEN PERFORM research_private.fail('not_found');END IF;
    IF key='budgets' THEN budgets:=budgets||pg_catalog.jsonb_build_array(selected);ELSE contributions:=contributions||pg_catalog.jsonb_build_array(selected);END IF;
   END LOOP;
  ELSIF key='budgets' AND pg_catalog.jsonb_array_length(src->key)>1 THEN PERFORM research_private.fail('conflict');
  ELSIF key='budgets' THEN budgets:=src->key;ELSE contributions:=src->key;END IF;
 END LOOP;
 d:=pg_catalog.jsonb_build_object('guidedVersion','4','title','טיוטת הסכם שותפות','studyIdentifier',src#>>'{study,id}','studyTitle',src#>>'{study,config,title}','requestedPermissions',src->'currentGrants');
 FOREACH key IN ARRAY ARRAY['guidedVersion','title','studyIdentifier','studyTitle'] LOOP fields:=fields||pg_catalog.jsonb_build_object(key,pg_catalog.jsonb_build_object('source','study','id',src#>>'{study,id}','revision',src#>'{study,revision}'));END LOOP;
 fields:=fields||pg_catalog.jsonb_build_object('requestedPermissions',pg_catalog.jsonb_build_object('source','current_membership','studyId',src#>>'{study,id}','partnerId',src#>>'{profile,id}'));
 -- A profile describes the operational researcher; legal contracting-party
 -- identity and signature authority remain explicit decisions.
 map:='{"fullName":"leadResearcher","institution":"leadResearcherInstitution","position":"leadResearcherRole"}';
 FOR key,target IN SELECT k,v#>>'{}' FROM pg_catalog.jsonb_each(map) x(k,v) LOOP IF src#>ARRAY['profile','data',key] IS NOT NULL THEN d:=d||pg_catalog.jsonb_build_object(target,src#>ARRAY['profile','data',key]);fields:=fields||pg_catalog.jsonb_build_object(target,pg_catalog.jsonb_build_object('source','profile','id',src#>>'{profile,id}','revision',src#>'{profile,revision}'));END IF;END LOOP;
 IF app->>'recordId' IS NOT NULL THEN
  d:=d||pg_catalog.jsonb_build_object('applicationId',app->'recordId');fields:=fields||pg_catalog.jsonb_build_object('applicationId',app-'data');
  map:='{"objectives":"objectives","researchQuestions":"researchQuestions","method":"method","population":"population","startDate":"startDate","endDate":"endDate","ethicsDetails":"ethicsApproval"}';
  FOR key,target IN SELECT k,v#>>'{}' FROM pg_catalog.jsonb_each(map) x(k,v) LOOP IF app#>ARRAY['data',key] IS NOT NULL THEN d:=d||pg_catalog.jsonb_build_object(target,app#>ARRAY['data',key]);fields:=fields||pg_catalog.jsonb_build_object(target,app-'data');END IF;END LOOP;
 END IF;
 map:='{"description":"purpose","researchQuestions":"researchQuestions","population":"population","startDate":"startDate","endDate":"endDate"}';
 FOR key,target IN SELECT k,v#>>'{}' FROM pg_catalog.jsonb_each(map) x(k,v) LOOP IF src#>ARRAY['study','config',key] IS NOT NULL THEN d:=d||pg_catalog.jsonb_build_object(target,src#>ARRAY['study','config',key]);fields:=fields||pg_catalog.jsonb_build_object(target,pg_catalog.jsonb_build_object('source','study','id',src#>>'{study,id}','revision',src#>'{study,revision}'));END IF;END LOOP;
 IF src#>'{study,config,approvals,documentation}' IS NOT NULL THEN d:=d||pg_catalog.jsonb_build_object('ethicsApproval',src#>'{study,config,approvals,documentation}');fields:=fields||pg_catalog.jsonb_build_object('ethicsApproval',pg_catalog.jsonb_build_object('source','study','revision',src#>'{study,revision}'));END IF;
 -- Tool names are the selected application's proposal; actions describe only
 -- current membership. Neither becomes an access grant through this document.
 annex:='[]';FOR item IN SELECT pg_catalog.jsonb_array_elements(COALESCE(app#>'{data,requestedTools}','[]')) LOOP annex:=annex||pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object('tool',item,'actions',src->'currentGrants','authorizedUsers',pg_catalog.jsonb_build_array(src#>>'{profile,id}')));END LOOP;
 IF annex='[]'::jsonb THEN annex:=pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object('actions',src->'currentGrants','authorizedUsers',pg_catalog.jsonb_build_array(src#>>'{profile,id}')));END IF;
 d:=d||pg_catalog.jsonb_build_object('toolIds',COALESCE(app#>'{data,requestedTools}','[]'),'annexB',annex);
 fields:=fields||pg_catalog.jsonb_build_object('toolIds',app-'data','annexB',pg_catalog.jsonb_build_object('source','current_membership_and_selected_application','applicationVersionId',app->'versionId','studyId',src#>>'{study,id}','partnerId',src#>>'{profile,id}'));
 IF EXISTS(SELECT 1 FROM pg_catalog.jsonb_array_elements(src->'forms') x WHERE x->>'kind'='consent') THEN
  d:=d||pg_catalog.jsonb_build_object('consentConfiguration',pg_catalog.jsonb_build_object('versions',(SELECT pg_catalog.jsonb_agg(x) FROM pg_catalog.jsonb_array_elements(src->'forms') x WHERE x->>'kind'='consent'),'recordedConfiguration',(SELECT pg_catalog.jsonb_object_agg(k,v) FROM pg_catalog.jsonb_each(src#>'{study,config}') x(k,v) WHERE k IN ('dataCategories','contactKinds','retentionDays','withdrawalPolicy','expectations')))::text);
  fields:=fields||pg_catalog.jsonb_build_object('consentConfiguration',src->'forms');
 END IF;
 selected:=(SELECT pg_catalog.jsonb_agg(x->'id') FROM pg_catalog.jsonb_array_elements(src->'forms') x WHERE x->>'kind'='instrument' AND x->'published'='true'::jsonb);
 IF selected IS NOT NULL THEN d:=d||pg_catalog.jsonb_build_object('questionnaireVersionIds',selected);fields:=fields||pg_catalog.jsonb_build_object('questionnaireVersionIds',src->'forms');END IF;
 selected:=(SELECT x->'id' FROM pg_catalog.jsonb_array_elements(src->'forms') x WHERE x->>'kind'='consent' AND x->'published'='true'::jsonb LIMIT 1);
 IF selected IS NOT NULL THEN d:=d||pg_catalog.jsonb_build_object('consentProtocolVersionId',selected);fields:=fields||pg_catalog.jsonb_build_object('consentProtocolVersionId',src->'forms');END IF;
 IF pg_catalog.jsonb_array_length(budgets)>0 THEN
  annex:='[]';FOR item IN SELECT pg_catalog.jsonb_array_elements(budgets) LOOP
   FOR selected IN SELECT pg_catalog.jsonb_array_elements(item#>'{data,items}') LOOP annex:=annex||pg_catalog.jsonb_build_array(pg_catalog.jsonb_strip_nulls(pg_catalog.jsonb_build_object('description',selected->'description','approvedCap',selected->'amount','currency',item#>'{data,currency}','settlementDate',selected->'dueDate','paymentTerms',selected->'terms','shareTerms',selected->'party')));END LOOP;
  END LOOP;
  d:=d||pg_catalog.jsonb_build_object('annexC',annex,'budgetId',budgets#>'{0,recordId}');fields:=fields||pg_catalog.jsonb_build_object('annexC',budgets-'data','budgetId',budgets#>'{0,versionId}');
 END IF;
 IF pg_catalog.jsonb_array_length(contributions)>0 THEN
  annex:='[]';selected:='[]';FOR item IN SELECT pg_catalog.jsonb_array_elements(contributions) LOOP
   selected:=selected||pg_catalog.jsonb_build_array(item->'recordId');annex:=annex||pg_catalog.jsonb_build_array(pg_catalog.jsonb_strip_nulls(pg_catalog.jsonb_build_object('contributionIdentifier',item->'recordId','description',item#>'{data,description}','deliverable',item#>'{data,deliverables}','category',item#>'{data,category}','requestedRecognition',item#>'{data,requestedRecognition}','requestedRights',item#>'{data,requestedIP}','requestedPayment',item#>'{data,requestedCompensation}','agreedRecognition',item#>'{approvedTerms,recognition}','agreedRights',item#>'{approvedTerms,ip}','agreedPayment',item#>'{approvedTerms,compensation}','ownerDuties',item#>'{approvedTerms,ownerObligations}','currency',COALESCE(item#>'{approvedTerms,currency}',item#>'{data,currency}'),'dueDate',item#>'{approvedTerms,deadline}','confirmingVersion',item->'versionId')));
  END LOOP;
  d:=d||pg_catalog.jsonb_build_object('contributionIds',selected,'annexD',annex);fields:=fields||pg_catalog.jsonb_build_object('contributionIds',contributions,'annexD',contributions);
 END IF;
 RETURN pg_catalog.jsonb_build_object('data',d,'fieldSources',fields,'selection',pg_catalog.jsonb_build_object('applicationVersionId',app->'versionId','budgetVersionIds',(SELECT COALESCE(pg_catalog.jsonb_agg(x->'versionId'),'[]') FROM pg_catalog.jsonb_array_elements(budgets) x),'contributionVersionIds',(SELECT COALESCE(pg_catalog.jsonb_agg(x->'versionId'),'[]') FROM pg_catalog.jsonb_array_elements(contributions) x)));
END $f$;

ALTER FUNCTION research_private.partnership_dispatch(text,text,jsonb) RENAME TO partnership_dispatch_before_guided;
CREATE FUNCTION research_private.guided_prepare(raw_token text,sid uuid,pid uuid,selection jsonb) RETURNS jsonb LANGUAGE plpgsql SET search_path='' AS $f$
DECLARE a jsonb;src jsonb;c jsonb;existing research_private.partnership_records;v research_private.partnership_versions;receipt research_private.agreement_preparations;t jsonb;r jsonb;BEGIN
 a:=research_private.guided_auth(raw_token,sid,pid,true);PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('guided-prepare:'||sid||':'||pid,0));PERFORM research_private.guided_lock_sources(sid,pid);
 src:=research_private.guided_sources(sid,pid);
 SELECT * INTO existing FROM research_private.partnership_records x WHERE x.study_id=sid AND x.partner_id=pid AND x.kind='agreement' ORDER BY x.created_at,x.id LIMIT 1 FOR UPDATE;
 IF existing.id IS NOT NULL THEN SELECT * INTO v FROM research_private.partnership_versions WHERE id=existing.head_version_id;SELECT * INTO receipt FROM research_private.agreement_preparations WHERE version_id=v.id;RETURN pg_catalog.jsonb_build_object('record',research_private.partnership_record(existing),'version',research_private.partnership_version(v),'template',NULL,'preparation',research_private.guided_receipt(receipt),'sources',src,'guidance',research_private.guided_catalog()-'templateData','resumed',true);END IF;
 c:=research_private.guided_candidate(src,selection);
 t:=research_private.partnership_dispatch_before_guided(raw_token,'recordSave',pg_catalog.jsonb_build_object('requestId',pg_catalog.gen_random_uuid(),'studyId',sid,'partnerId',pid,'kind','agreement_template','data',research_private.guided_catalog()->'templateData','expectedRevision',NULL));IF t ? 'error' THEN PERFORM research_private.fail(t->>'error');END IF;
 r:=research_private.partnership_dispatch_before_guided(raw_token,'recordSave',pg_catalog.jsonb_build_object('requestId',pg_catalog.gen_random_uuid(),'studyId',sid,'partnerId',pid,'kind','agreement','data',(c->'data')||pg_catalog.jsonb_build_object('templateVersionId',t#>'{version,id}','ipExplanationVersionId',t#>'{version,id}'),'expectedRevision',NULL));IF r ? 'error' THEN PERFORM research_private.fail(r->>'error');END IF;
 INSERT INTO research_private.agreement_preparations(study_id,partner_id,record_id,version_id,snapshot,field_sources,source_hash,created_by) VALUES(sid,pid,(r#>>'{record,id}')::uuid,(r#>>'{version,id}')::uuid,pg_catalog.jsonb_build_object('sources',src,'selection',c->'selection','candidate',c->'data'),c->'fieldSources',research_private.partnership_hash(src),a->>'actor') RETURNING * INTO receipt;
 RETURN r||pg_catalog.jsonb_build_object('template',t,'preparation',research_private.guided_receipt(receipt),'sources',src,'guidance',research_private.guided_catalog()-'templateData','resumed',false);
END $f$;

CREATE FUNCTION research_private.guided_preview(sid uuid,pid uuid,body jsonb) RETURNS jsonb LANGUAGE plpgsql SET search_path='' AS $f$
DECLARE src jsonb;c jsonb;r research_private.partnership_records;v research_private.partnership_versions;p research_private.agreement_preparations;changes jsonb:='[]';keys text[];key text;choice jsonb;preview jsonb;collection text;mapped jsonb;item jsonb;replacement jsonb;BEGIN
 SELECT * INTO r FROM research_private.partnership_records WHERE id=(body->>'recordId')::uuid AND study_id=sid AND partner_id=pid AND kind='agreement' FOR UPDATE;
 IF r.id IS NULL THEN PERFORM research_private.fail('not_found');END IF;
 IF r.head_version_id IS DISTINCT FROM (body->>'versionId')::uuid OR r.status IN ('signing','executed','retired') THEN PERFORM research_private.fail('conflict');END IF;
 SELECT * INTO v FROM research_private.partnership_versions WHERE id=r.head_version_id;SELECT * INTO p FROM research_private.agreement_preparations WHERE version_id=v.id;
 IF p.id IS NULL THEN PERFORM research_private.fail('conflict');END IF;
 src:=research_private.guided_sources(sid,pid);choice:=pg_catalog.jsonb_strip_nulls(COALESCE(p.snapshot->'selection','{}'));
 -- Omitted selections resume the same records at their current eligible head.
 IF NOT(body ? 'applicationVersionId') AND choice ? 'applicationVersionId' THEN choice:=pg_catalog.jsonb_set(choice,'{applicationVersionId}',COALESCE((SELECT x->'versionId' FROM pg_catalog.jsonb_array_elements(src->'applications') x WHERE x->>'recordId'=p.snapshot#>>'{candidate,applicationId}'),choice->'applicationVersionId'));END IF;
 FOREACH key IN ARRAY ARRAY['budgetVersionIds','contributionVersionIds'] LOOP
  collection:=CASE key WHEN 'budgetVersionIds' THEN 'budgets' ELSE 'contributions' END;
  IF NOT(body ? key) AND choice ? key THEN
   mapped:='[]';FOR item IN SELECT pg_catalog.jsonb_array_elements(choice->key) LOOP
    SELECT current_source->'versionId' INTO replacement FROM pg_catalog.jsonb_array_elements(src->collection) current_source JOIN pg_catalog.jsonb_array_elements(p.snapshot#>ARRAY['sources',collection]) previous_source ON current_source->>'recordId'=previous_source->>'recordId' WHERE previous_source->'versionId'=item;
    mapped:=mapped||pg_catalog.jsonb_build_array(COALESCE(replacement,item));
   END LOOP;choice:=pg_catalog.jsonb_set(choice,ARRAY[key],mapped);
  END IF;
 END LOOP;
 FOREACH key IN ARRAY ARRAY['applicationVersionId','budgetVersionIds','contributionVersionIds'] LOOP IF body ? key THEN choice:=choice||pg_catalog.jsonb_build_object(key,body->key);END IF;END LOOP;
 c:=research_private.guided_candidate(src,choice);
 SELECT ARRAY(SELECT DISTINCT k FROM (SELECT pg_catalog.jsonb_object_keys(c->'data') k UNION SELECT pg_catalog.jsonb_object_keys(p.snapshot->'candidate') k UNION SELECT pg_catalog.jsonb_object_keys(p.field_sources) k) x ORDER BY k) INTO keys;
 FOREACH key IN ARRAY keys LOOP IF v.data->key IS DISTINCT FROM c#>ARRAY['data',key] THEN changes:=changes||pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object('field',key,'current',v.data->key,'proposed',c#>ARRAY['data',key],'proposedPresent',(c->'data') ? key,'overridden',p.overrides ? key,'source',c#>ARRAY['fieldSources',key]));END IF;END LOOP;
 preview:=pg_catalog.jsonb_build_object('recordId',r.id,'versionId',v.id,'expectedRevision',r.revision,'sourceHash',research_private.partnership_hash(src),'sources',src,'selection',c->'selection','changes',changes,'candidate',c->'data','fieldSources',c->'fieldSources','overrides',p.overrides,'initialReceiptId',COALESCE(p.initial_receipt_id,p.id));
 RETURN preview||pg_catalog.jsonb_build_object('hash',research_private.partnership_hash(preview));
END $f$;

CREATE FUNCTION research_private.processing_policy_json(p research_private.processing_policies) RETURNS jsonb LANGUAGE sql STABLE SET search_path='' AS $f$
 SELECT CASE WHEN p.id IS NULL THEN NULL ELSE pg_catalog.jsonb_build_object('id',p.id,'studyId',p.study_id,'partnerId',p.partner_id,'revision',p.revision,'data',p.policy,'hash',p.policy_hash,'restrictionHash',p.restriction_hash,'approved',EXISTS(SELECT 1 FROM research_private.processing_policy_approvals a WHERE a.policy_id=p.id),'current',p.restriction_hash=research_private.guided_restrictions(p.study_id)) END $f$;
-- Internal route decision only: callers must calculate categories from the exact
-- minimized transfer. This helper never treats editable clauses as permission.
CREATE FUNCTION research_private.processing_authorized(raw_token text,sid uuid,pid uuid,purpose text,provider text,provider_version text,categories jsonb) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $f$
DECLARE a jsonb;p research_private.processing_policies;allowed boolean;BEGIN
 a:=research_private.guided_auth(raw_token,sid,pid);PERFORM pg_catalog.set_config('research.owner','true',true);
 SELECT * INTO p FROM research_private.processing_policies x WHERE x.study_id=sid AND x.partner_id=pid ORDER BY revision DESC LIMIT 1;
 allowed:=p.id IS NOT NULL AND p.restriction_hash=research_private.guided_restrictions(sid) AND EXISTS(SELECT 1 FROM research_private.processing_policy_approvals x WHERE x.policy_id=p.id) AND p.policy->>'purpose'=purpose AND p.policy->>'provider'=provider AND p.policy->>'providerVersion'=provider_version AND pg_catalog.jsonb_typeof(categories)='array' AND pg_catalog.jsonb_array_length(categories)>0 AND categories<@(p.policy->'dataCategories') AND (p.policy->'authorizedActors') ? (a->>'actor');
 PERFORM research_private.intake_reset();RETURN COALESCE(allowed,false);
END $f$;

CREATE FUNCTION research_private.guided_request(action text,body jsonb) RETURNS void LANGUAGE plpgsql SET search_path='' AS $f$
DECLARE k text;typ text;v jsonb;x jsonb;BEGIN
 FOR k,typ IN SELECT key,value#>>'{}' FROM pg_catalog.jsonb_each(research_private.partnership_contract()#>ARRAY['operations',action,'request']) LOOP
  v:=body->k;IF v IS NULL THEN IF pg_catalog.strpos(typ,'?')=0 THEN PERFORM research_private.fail('invalid');END IF;CONTINUE;END IF;
  IF typ LIKE 'uuid[]%' OR typ LIKE 'string[]%' THEN
   IF pg_catalog.jsonb_typeof(v)<>'array' OR pg_catalog.jsonb_array_length(v)>200 OR (SELECT pg_catalog.count(*)<>pg_catalog.count(DISTINCT item) FROM pg_catalog.jsonb_array_elements(v) item) THEN PERFORM research_private.fail('invalid');END IF;
   FOR x IN SELECT pg_catalog.jsonb_array_elements(v) LOOP IF pg_catalog.jsonb_typeof(x)<>'string' OR pg_catalog.length(x#>>'{}')>500 OR typ LIKE 'uuid[]%' AND x#>>'{}'!~*'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$' THEN PERFORM research_private.fail('invalid');END IF;END LOOP;
  ELSIF typ LIKE 'uuid%' THEN IF pg_catalog.jsonb_typeof(v)<>'string' OR v#>>'{}'!~*'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$' THEN PERFORM research_private.fail('invalid');END IF;
  ELSIF typ='integer' THEN IF pg_catalog.jsonb_typeof(v)<>'number' OR v#>>'{}'!~'^[0-9]+$' OR (v#>>'{}')::numeric>9007199254740991 THEN PERFORM research_private.fail('invalid');END IF;
  ELSIF typ='sha256' THEN IF pg_catalog.jsonb_typeof(v)<>'string' OR v#>>'{}'!~'^[a-f0-9]{64}$' THEN PERFORM research_private.fail('invalid');END IF;
  ELSIF k='policy' THEN IF pg_catalog.jsonb_typeof(v)<>'object' THEN PERFORM research_private.fail('invalid');END IF;
  ELSE PERFORM research_private.fail('invalid');END IF;
 END LOOP;
 IF body ? 'requestId' AND (pg_catalog.jsonb_typeof(body->'requestId')<>'string' OR body->>'requestId'!~*'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$') THEN PERFORM research_private.fail('invalid');END IF;
END $f$;
CREATE FUNCTION research_private.partnership_dispatch(p_token text,p_action text,p_payload jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $f$
#variable_conflict use_variable
DECLARE sid uuid;pid uuid;a jsonb;result jsonb;src jsonb;preview jsonb;data jsonb;key text;old_version uuid;prior research_private.agreement_preparations;receipt research_private.agreement_preparations;replay research_private.partnership_receipts;pol research_private.processing_policies;overrides jsonb;hash text;scope text;field_sources jsonb;BEGIN
 IF p_action NOT IN ('agreementSources','agreementPrepare','agreementRefreshPreview','agreementRefreshApply','processingPolicyGet','processingPolicySave','processingPolicyApprove') THEN
  -- Existing author edits acquire server-owned override metadata independently
  -- from the editable agreement data, including intentional empty values.
   IF (p_action='recordSave' AND p_payload->>'kind'='agreement' OR p_action='agreementAmend') AND p_payload ? 'recordId' THEN
   result:=research_private.partnership_dispatch_before_guided(p_token,p_action,p_payload);IF result ? 'error' THEN RETURN result;END IF;
   SELECT x.* INTO prior FROM research_private.agreement_preparations x JOIN research_private.partnership_versions pv ON pv.id=x.version_id WHERE x.record_id=CASE WHEN p_action='agreementAmend' THEN (p_payload->>'recordId')::uuid ELSE (result#>>'{record,id}')::uuid END ORDER BY pv.number DESC LIMIT 1;
   IF prior.id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM research_private.agreement_preparations WHERE version_id=(result#>>'{version,id}')::uuid) THEN
    overrides:=prior.overrides;FOR key IN SELECT pg_catalog.jsonb_object_keys((SELECT v.data FROM research_private.partnership_versions v WHERE id=prior.version_id)||p_payload->'data') LOOP IF (SELECT v.data->key FROM research_private.partnership_versions v WHERE id=prior.version_id) IS DISTINCT FROM p_payload#>ARRAY['data',key] AND NOT(overrides ? key) THEN overrides:=overrides||pg_catalog.jsonb_build_array(key);END IF;END LOOP;
    INSERT INTO research_private.agreement_preparations(study_id,partner_id,record_id,version_id,initial_receipt_id,snapshot,field_sources,overrides,source_hash,created_by) VALUES(prior.study_id,prior.partner_id,(result#>>'{record,id}')::uuid,(result#>>'{version,id}')::uuid,COALESCE(prior.initial_receipt_id,prior.id),prior.snapshot,prior.field_sources,overrides,prior.source_hash,pg_catalog.current_setting('research.actor',true));
   END IF;RETURN result;
  END IF;
  RETURN research_private.partnership_dispatch_before_guided(p_token,p_action,p_payload);
 END IF;
 IF pg_catalog.jsonb_typeof(p_payload) IS DISTINCT FROM 'object' THEN PERFORM research_private.fail('invalid');END IF;
 PERFORM research_private.guided_request(p_action,p_payload);
 IF p_payload->'expectedRevision'='null'::jsonb THEN PERFORM research_private.fail('invalid');END IF;
 FOREACH key IN ARRAY ARRAY['budgetVersionIds','contributionVersionIds'] LOOP IF p_payload ? key AND (SELECT pg_catalog.count(*)<>pg_catalog.count(DISTINCT x) FROM pg_catalog.jsonb_array_elements(p_payload->key) x) THEN PERFORM research_private.fail('invalid');END IF;END LOOP;
 FOR key IN SELECT pg_catalog.jsonb_object_keys(p_payload) LOOP IF key<>'requestId' AND NOT(research_private.partnership_contract()#>ARRAY['operations',p_action,'request'] ? key) THEN PERFORM research_private.fail('invalid');END IF;END LOOP;
 sid:=(p_payload->>'studyId')::uuid;pid:=(p_payload->>'partnerId')::uuid;
 a:=research_private.guided_auth(p_token,sid,pid,p_action IN ('agreementPrepare','processingPolicyGet','processingPolicySave','processingPolicyApprove'),p_action='processingPolicyGet');
 IF NOT(research_private.partnership_contract()->'reads' ? p_action) THEN
  IF p_payload->>'requestId' IS NULL THEN PERFORM research_private.fail('invalid');END IF;scope:=sid||':'||pid;hash:=research_private.partnership_hash(p_payload-'requestId');
  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended((a->>'actor')||scope||p_action||(p_payload->>'requestId'),0));
  SELECT * INTO replay FROM research_private.partnership_receipts x WHERE x.actor_ref=a->>'actor' AND x.scope=scope AND x.action=p_action AND x.request_id=(p_payload->>'requestId')::uuid;
  IF replay.request_id IS NOT NULL THEN IF replay.payload_hash<>hash THEN PERFORM research_private.fail('conflict');END IF;RETURN replay.result;END IF;
 END IF;
 IF p_action='agreementSources' THEN result:=pg_catalog.jsonb_build_object('sources',research_private.guided_sources(sid,pid),'guidance',research_private.guided_catalog()-'templateData');
 ELSIF p_action='agreementPrepare' THEN result:=research_private.guided_prepare(p_token,sid,pid,p_payload);
 ELSIF p_action IN ('agreementRefreshPreview','agreementRefreshApply') THEN
  PERFORM research_private.guided_lock_sources(sid,pid);
  preview:=research_private.guided_preview(sid,pid,p_payload);
  IF p_action='agreementRefreshPreview' THEN result:=pg_catalog.jsonb_build_object('preview',preview);
  ELSE
   IF preview->>'hash' IS DISTINCT FROM p_payload->>'previewHash' OR preview->'expectedRevision' IS DISTINCT FROM p_payload->'expectedRevision' THEN PERFORM research_private.fail('conflict');END IF;
   IF (SELECT pg_catalog.count(*)<>pg_catalog.count(DISTINCT x) FROM pg_catalog.jsonb_array_elements(p_payload->'replaceFields') x) THEN PERFORM research_private.fail('invalid');END IF;
   SELECT v.data INTO data FROM research_private.partnership_versions v WHERE v.id=(p_payload->>'versionId')::uuid;
   SELECT p.field_sources INTO field_sources FROM research_private.agreement_preparations p WHERE p.version_id=(p_payload->>'versionId')::uuid;
   overrides:=preview->'overrides';
   FOR key IN SELECT pg_catalog.jsonb_array_elements_text(p_payload->'replaceFields') LOOP
    IF NOT EXISTS(SELECT 1 FROM pg_catalog.jsonb_array_elements(preview->'changes') c WHERE c->>'field'=key) THEN PERFORM research_private.fail('invalid');END IF;
    IF preview->'candidate' ? key THEN data:=data||pg_catalog.jsonb_build_object(key,preview#>ARRAY['candidate',key]);ELSE data:=data-key;END IF;overrides:=overrides-key;
    IF preview->'fieldSources' ? key THEN field_sources:=field_sources||pg_catalog.jsonb_build_object(key,preview#>ARRAY['fieldSources',key]);ELSE field_sources:=field_sources-key;END IF;
   END LOOP;
   result:=research_private.partnership_dispatch_before_guided(p_token,'recordSave',pg_catalog.jsonb_build_object('requestId',p_payload->'requestId','studyId',sid,'partnerId',pid,'recordId',p_payload->'recordId','kind','agreement','data',data,'expectedRevision',p_payload->'expectedRevision'));IF result ? 'error' THEN PERFORM research_private.fail(result->>'error');END IF;
   INSERT INTO research_private.agreement_preparations(study_id,partner_id,record_id,version_id,initial_receipt_id,snapshot,field_sources,overrides,source_hash,created_by) VALUES(sid,pid,(result#>>'{record,id}')::uuid,(result#>>'{version,id}')::uuid,(preview->>'initialReceiptId')::uuid,pg_catalog.jsonb_build_object('sources',preview->'sources','selection',preview->'selection','candidate',preview->'candidate'),field_sources,overrides,preview->>'sourceHash',a->>'actor') RETURNING * INTO receipt;
   result:=result||pg_catalog.jsonb_build_object('preparation',research_private.guided_receipt(receipt));
  END IF;
 ELSE
  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('processing-policy:'||sid||':'||pid,0));
  SELECT * INTO pol FROM research_private.processing_policies x WHERE x.study_id=sid AND x.partner_id=pid ORDER BY revision DESC LIMIT 1;
  IF p_action<>'processingPolicyGet' AND COALESCE(pol.revision,0)<>(p_payload->>'expectedRevision')::integer THEN PERFORM research_private.fail('conflict');END IF;
  IF p_action='processingPolicySave' THEN
   PERFORM research_private.partnership_fields(research_private.partnership_contract()->'processingPolicy',p_payload->'policy',sid,pid,true);
   IF EXISTS(SELECT 1 FROM pg_catalog.jsonb_array_elements_text(p_payload#>'{policy,authorizedActors}') x WHERE x NOT IN ('sys',(SELECT p.actor_ref FROM research_private.partnership_partners p WHERE p.id=pid))) THEN PERFORM research_private.fail('invalid');END IF;
   INSERT INTO research_private.processing_policies(study_id,partner_id,revision,policy,policy_hash,restriction_hash,created_by) VALUES(sid,pid,COALESCE(pol.revision,0)+1,p_payload->'policy',research_private.partnership_hash(p_payload->'policy'),research_private.guided_restrictions(sid),a->>'actor') RETURNING * INTO pol;
  ELSIF p_action='processingPolicyApprove' THEN
   IF pol.id IS DISTINCT FROM (p_payload->>'policyVersionId')::uuid OR pol.policy_hash IS DISTINCT FROM p_payload->>'policyHash' OR pol.restriction_hash IS DISTINCT FROM research_private.guided_restrictions(sid) THEN PERFORM research_private.fail('conflict');END IF;
   IF pol.policy->'dataCategories' ? 'personal' AND NOT EXISTS(SELECT 1 FROM research_private.studies s JOIN research_private.form_versions v ON v.study_id=s.id AND v.id=(s.config->>'consentVersionId')::uuid JOIN research_private.form_publications fp ON fp.study_id=s.id AND fp.version_id=v.id WHERE s.id=sid AND s.config#>>'{approvals,status}'='approved') THEN PERFORM research_private.fail('conflict');END IF;
   INSERT INTO research_private.processing_policy_approvals(policy_id,approved_by) VALUES(pol.id,a->>'actor') ON CONFLICT DO NOTHING;
  END IF;
  result:=pg_catalog.jsonb_build_object('policy',research_private.processing_policy_json(pol));
 END IF;
 IF NOT(research_private.partnership_contract()->'reads' ? p_action) THEN
  -- Inner legacy calls can reset context; recover current authenticated scope.
  PERFORM research_private.guided_auth(p_token,sid,pid,p_action IN ('agreementPrepare','processingPolicySave','processingPolicyApprove'));
  INSERT INTO research_private.partnership_receipts(actor_ref,scope,action,request_id,payload_hash,result) VALUES(a->>'actor',scope,p_action,(p_payload->>'requestId')::uuid,hash,result);
 END IF;
 RETURN result;
EXCEPTION WHEN SQLSTATE 'P0001' THEN RETURN pg_catalog.jsonb_build_object('error',SQLERRM);WHEN invalid_text_representation OR numeric_value_out_of_range OR unique_violation OR foreign_key_violation OR check_violation THEN RETURN '{"error":"invalid"}';
END $f$;

ALTER FUNCTION research_private.intake_dispatch(text,text,jsonb) RENAME TO intake_dispatch_before_guided;
CREATE FUNCTION research_private.intake_dispatch(p_token text,p_action text,p_payload jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $f$
#variable_conflict use_variable
DECLARE result jsonb;prepared jsonb;selection jsonb;a jsonb;replayed jsonb;scope text;hash text;s research_private.studies;p research_private.partnership_partners;BEGIN
 result:=research_private.intake_dispatch_before_guided(p_token,p_action,p_payload);
 IF result ? 'error' THEN RETURN result;END IF;
 IF p_action='intakeReview' AND p_payload->>'decision'='approved' THEN
  a:=research_private.guided_auth(p_token,(result#>>'{application,studyId}')::uuid,(result#>>'{application,partnerId}')::uuid,true);
  scope:=(result#>>'{application,studyId}')||':'||(result#>>'{application,partnerId}');hash:=research_private.partnership_hash(p_payload-'requestId');
  SELECT r.result INTO replayed FROM research_private.partnership_receipts r WHERE r.actor_ref=a->>'actor' AND r.scope=scope AND r.action='intakeGuidedHandoff' AND r.request_id=(p_payload->>'requestId')::uuid AND r.payload_hash=hash;
  IF replayed IS NOT NULL THEN RETURN replayed;END IF;
  selection:=pg_catalog.jsonb_build_object('applicationVersionId',(SELECT r.head_version_id FROM research_private.partnership_records r WHERE r.id=(result#>>'{application,recordId}')::uuid));
  prepared:=research_private.guided_prepare(p_token,(result#>>'{application,studyId}')::uuid,(result#>>'{application,partnerId}')::uuid,selection);
  result:=result||pg_catalog.jsonb_build_object('preparation',prepared);
  SELECT * INTO s FROM research_private.studies WHERE id=(result#>>'{application,studyId}')::uuid;SELECT * INTO p FROM research_private.partnership_partners WHERE id=(result#>>'{application,partnerId}')::uuid;
  result:=result||pg_catalog.jsonb_build_object('workspace',research_private.partnership_workspace(s,p));
  INSERT INTO research_private.partnership_receipts(actor_ref,scope,action,request_id,payload_hash,result) VALUES(a->>'actor',scope,'intakeGuidedHandoff',(p_payload->>'requestId')::uuid,hash,result);
 END IF;
 RETURN result;
EXCEPTION WHEN SQLSTATE 'P0001' THEN RETURN pg_catalog.jsonb_build_object('error',SQLERRM);WHEN invalid_text_representation OR numeric_value_out_of_range OR unique_violation OR foreign_key_violation OR check_violation THEN RETURN '{"error":"invalid"}';
END $f$;

GRANT CREATE ON SCHEMA research_private TO research_worker;
ALTER FUNCTION research_private.partnership_dispatch(text,text,jsonb) OWNER TO research_worker;
ALTER FUNCTION research_private.intake_dispatch(text,text,jsonb) OWNER TO research_worker;
ALTER FUNCTION research_private.processing_authorized(text,uuid,uuid,text,text,text,jsonb) OWNER TO research_worker;
REVOKE CREATE ON SCHEMA research_private FROM research_worker;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA research_private FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON ALL FUNCTIONS IN SCHEMA research_private TO research_worker;
GRANT EXECUTE ON FUNCTION research_private.dispatch(text,text,jsonb),research_private.partnership_dispatch(text,text,jsonb),research_private.intake_dispatch(text,text,jsonb),research_private.intake_reset() TO service_role;
COMMIT;
